{"version":3,"sources":["powpow/item-portfolio.scss","powpow/item-portfolio.css"],"names":[],"mappings":"AAAA;EACI,gBAAA;EACA,mBAAA;EACA,gBAAA;EACA,0CAAA;ACCJ;;ADEA;EACI,aAAA;ACCJ;;ADEA;EACI,mBAAA;EACA,eAAA;EACA,gBAAA;ACCJ;;ADEA;EACI,aAAA;EACA,8BAAA;EACA,kBAAA;ACCJ;;ADEA;EACI,OAAA;ACCJ;;ADEA;EACI,cAAA;EACA,eAAA;EACA,gBAAA;ACCJ;;ADEA;EACI,cAAA;EACA,eAAA;EACA,WAAA;ACCJ;;ADEA;EACI,aAAA;ACCJ;;ADEA;EACI,aAAA;EACA,8BAAA;EACA,mBAAA;EACA,SAAA;EACA,oBAAA;ACCJ;;ADEA;EACI,iBAAA;EACA,gBAAA;EACA,cAAA;EACA,0BAAA;EACA,iBAAA;EACA,gBAAA;ACCJ;;ADEA;EACI,OAAA;EACA,aAAA;EACA,uBAAA;EACA,mBAAA;EACA,QAAA;EACA,kBAAA;EACA,gBAAA;EACA,gBAAA;ACCJ;;ADEA;EACI,kBAAA;ACCJ;;ADGA;EACI,aAAA;EACA,uBAAA;EACA,QAAA;ACAJ;;ADGA;EACI,OAAA;EACA,aAAA;EACA,sBAAA,EAAA,6BAAA;EACA,mBAAA;EACA,uBAAA;EACA,kBAAA;EACA,QAAA;EACA,eAAA;ACAJ;;ADGA;EACI,gBAAA;EACA,cAAA;ACAJ;;ADGA;EACI,gBAAA;EACA,gBAAA;EACA,mBAAA;ACAJ;;ADKA;EACI,aAAA;ACFJ;;ADKA;EACI,aAAA;EACA,oBAAA;KAAA,iBAAA;ACFJ;;ADKA;EACI,uBAAA;ACFJ;;ADKA;EACI,iBAAA;EACA,eAAA;EACA,mBAAA;EAEA,kBAAA;EACA,gBAAA;EACA,kBAAA;ACHJ;;ADMA;EACI,iBAAA;ACHJ;;ADMA;EACI,iBAAA;ACHJ;;ADMA;EACI,8BAAA;ACHJ;;ADMA;EACI;IAEI,gBAAA;IACA,kBAAA;ECJN;EDOE;IAEI,gBAAA;ECNN;AACF","file":"item-portfolio.css","sourcesContent":[".portfolio-card{\n    background:#fff;\n    border-radius:12px;\n    overflow:hidden;\n    box-shadow:0 5px 20px rgba(0,0,0,.08);\n}\n\n.portfolio-info{\n    padding:18px;\n}\n\n.portfolio-info h4{\n    margin-bottom:15px;\n    font-size:20px;\n    font-weight:600;\n}\n\n.portfolio-stats{\n    display:flex;\n    justify-content:space-between;\n    text-align:center;\n}\n\n.stat{\n    flex:1;\n}\n\n.number{\n    display:block;\n    font-size:24px;\n    font-weight:700;\n}\n\n.label{\n    display:block;\n    font-size:13px;\n    color:#777;\n}\n\n.portfolio-info{\n    padding:18px;\n}\n\n.project-stats{\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    gap: 10px;\n    margin-bottom: 1.3vw;\n}\n\n.project-description {\n    font-size: 0.9rem;\n    line-height: 1.5;\n    color: #6c757d;\n    border-top: 1px solid #eee;\n    padding-top: 12px;\n    margin-top: 10px;\n}\n\n.stat{\n    flex: 1;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    gap: 6px;\n    text-align: center;\n    font-size: 1.3vw;\n    font-weight: 500;\n}\n\n.portfolio-info{\n    padding: 24px 18px;\n}\n\n\n.project-stats{\n    display: flex;\n    justify-content: center;\n    gap: 1vw;\n}       \n\n.stat{\n    flex: 1;\n    display: flex;\n    flex-direction: column;    /* Icona sopra, testo sotto */\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    gap: 8px;\n    margin-top: 5px;\n}\n\n.stat i{\n    font-size: 1.2em;\n    color: #4a90e2;\n}\n\n.stat span{\n    font-size: 0.7em;\n    font-weight: 500;\n    white-space: nowrap;\n}\n\n\n\n.portfolio-card {\n    height: 460px;\n}\n\n.portfolio-card .image img {\n    height: 160px;\n    object-fit: cover;\n}\n\n.portfolio-info {\n    padding: 10px 12px 12px;\n}\n\n.project-title {\n    font-size: 1.5rem;\n    margin-top: 5px;\n    margin-bottom: 10px;\n\n    text-align: center;\n    font-weight:600;\n    line-height: 1.2em;\n}\n\n.project-stats {\n    font-size: 0.8rem;\n}\n\n.project-stats .stat {\n    margin-right: 8px;\n}\n\n.mb-4 {\n    margin-bottom: 1rem !important;\n}\n\n@media (max-width: 720px) {\n    .project-stats\n    {\n        margin-top: 20px;\n        margin-bottom: 0px;\n    }\n\n    .stat\n    {\n        font-size: 2.4vw;\n    }\n}",".portfolio-card {\n  background: #fff;\n  border-radius: 12px;\n  overflow: hidden;\n  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.08);\n}\n\n.portfolio-info {\n  padding: 18px;\n}\n\n.portfolio-info h4 {\n  margin-bottom: 15px;\n  font-size: 20px;\n  font-weight: 600;\n}\n\n.portfolio-stats {\n  display: flex;\n  justify-content: space-between;\n  text-align: center;\n}\n\n.stat {\n  flex: 1;\n}\n\n.number {\n  display: block;\n  font-size: 24px;\n  font-weight: 700;\n}\n\n.label 